def checked_radix_sort(nums):
    if not nums:
        return nums
    RADIX = 10
    max_num = max(nums)
    if max_num < 0:
        return sorted(nums, reverse=True)
    placement = 1
    while placement <= max_num:
        buckets = [[] for _ in range(RADIX)]
        for i in nums:
            digit = (i // placement) % RADIX
            buckets[digit].append(i)
        a = 0
        for b in range(RADIX - 1, -1, -1):
            buck = buckets[b]
            for i in buck:
                nums[a] = i
                a += 1
        placement *= RADIX
    return nums
