def area_of_polygon_inside_circle(circle_radius, number_of_sides):
    import math
    # Normalize input if needed (though examples use numbers directly)
    if isinstance(number_of_sides, str):
        number_of_sides = number_of_sides.replace("number-of-", "").replace("number_", "").replace("-", "").strip()
