def maximum_product_of_parts(number):
    s = str(number)
    n = len(s)
    result = 0
    for i in range(2, n - 1):
        for j in range(i + 1, n):
            start = int(s[0:i])
            middle = int(s[i:j])
            end = int(s[j:n])
            result = max(result, start * middle * end)
    return result

